// Real shapes from examples/features today.
fn label(n: Int) => String {
    return if {
        n % 15 == 0 -> "FizzBuzz"
        n % 3 == 0 -> "Fizz"
        else -> "{n}"
    }
}

fn report(rows: [Int]) =[IO]=> {
    loop n, rows -> print(label(n))
    bumped :: rows.lazy().map(value => value + 1)
    print(bumped.count())
}

