comparisons.code:
fn label(n: i64) -> String {
    match n % 15 {
        0 => "FizzBuzz".to_string(),
        _ => n.to_string(),
    }
}

def label(n: Int): String = n % 15 match {
  case 0 => "FizzBuzz"
  case _ => n.toString
}
val bump = (v: Int) => v + 1

func label(n int) string {
    switch n % 15 {
    case 0:
        return "FizzBuzz"
    }
    return strconv.Itoa(n)
}
